SELECT 'Électricité', 1, '#f3dc25', '⚡️'
WHERE NOT EXISTS (SELECT 1 FROM category WHERE name = 'Électricité');
INSERT INTO category (name, type, color, icon)
SELECT 'Mobile', 1, '#a3efff', '📞'
WHERE NOT EXISTS (SELECT 1 FROM category WHERE name = 'Mobile');
